DROP DATABASE IF EXISTS datacenter_ia;
CREATE DATABASE datacenter_ia CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE datacenter_ia;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE zona_cluster (
    id_zona INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    nome_zona VARCHAR(50) NOT NULL UNIQUE,
    descricao VARCHAR(255),
    ativo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE turno (
    id_turno INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    nome_turno VARCHAR(20) NOT NULL UNIQUE
);

CREATE TABLE status_eficiencia (
    id_status INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    nome_status VARCHAR(20) NOT NULL UNIQUE,
    descricao VARCHAR(255)
);

CREATE TABLE parametros_sustentabilidade (
    id_parametro INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    data_inicio DATE NOT NULL,
    data_fim DATE NULL,
    tarifa_energia_kwh DECIMAL(10,4) NOT NULL,
    tarifa_agua_m3 DECIMAL(10,4) NOT NULL,
    fator_emissao_co2 DECIMAL(10,6) NOT NULL,
    descricao VARCHAR(255),
    CONSTRAINT chk_parametro_datas CHECK (data_fim IS NULL OR data_fim >= data_inicio),
    CONSTRAINT chk_tarifa_energia CHECK (tarifa_energia_kwh >= 0),
    CONSTRAINT chk_tarifa_agua CHECK (tarifa_agua_m3 >= 0),
    CONSTRAINT chk_fator_co2 CHECK (fator_emissao_co2 >= 0)
);

CREATE TABLE medicao_datacenter (
    id_medicao BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    id_registro_csv INT UNSIGNED NOT NULL UNIQUE,
    data_hora DATETIME NOT NULL,
    id_zona INT UNSIGNED NOT NULL,
    id_turno INT UNSIGNED NOT NULL,
    id_status INT UNSIGNED NOT NULL,
    consumo_total_kwh DECIMAL(20,14) NOT NULL,
    energia_gpus_kwh DECIMAL(20,14) NOT NULL,
    energia_refrigeracao_kwh DECIMAL(20,14) NOT NULL,
    consumo_agua_l DECIMAL(20,14) NOT NULL,
    agua_reaproveitada_l DECIMAL(20,14) NOT NULL,
    utilizacao_gpus_pct DECIMAL(20,14) NOT NULL,
    eficiencia_energetica_pct DECIMAL(20,14) NOT NULL,
    eficiencia_hidrica_pct DECIMAL(20,14) NOT NULL,
    CONSTRAINT fk_medicao_zona FOREIGN KEY (id_zona) REFERENCES zona_cluster(id_zona),
    CONSTRAINT fk_medicao_turno FOREIGN KEY (id_turno) REFERENCES turno(id_turno),
    CONSTRAINT fk_medicao_status FOREIGN KEY (id_status) REFERENCES status_eficiencia(id_status),
    CONSTRAINT chk_consumo_total CHECK (consumo_total_kwh >= 0),
    CONSTRAINT chk_energia_gpu CHECK (energia_gpus_kwh >= 0),
    CONSTRAINT chk_energia_refrigeracao CHECK (energia_refrigeracao_kwh >= 0),
    CONSTRAINT chk_consumo_agua CHECK (consumo_agua_l >= 0),
    CONSTRAINT chk_agua_reaproveitada CHECK (agua_reaproveitada_l >= 0),
    CONSTRAINT chk_utilizacao_gpu CHECK (utilizacao_gpus_pct BETWEEN 0 AND 100),
    CONSTRAINT chk_eficiencia_energetica CHECK (eficiencia_energetica_pct BETWEEN 0 AND 100),
    CONSTRAINT chk_eficiencia_hidrica CHECK (eficiencia_hidrica_pct BETWEEN 0 AND 100)
);

CREATE INDEX idx_medicao_data_hora ON medicao_datacenter(data_hora);
CREATE INDEX idx_medicao_zona_data ON medicao_datacenter(id_zona, data_hora);
CREATE INDEX idx_medicao_turno_data ON medicao_datacenter(id_turno, data_hora);
CREATE INDEX idx_medicao_status_data ON medicao_datacenter(id_status, data_hora);




-- Parâmetros acadêmicos para permitir estimativas de custo e CO2.
-- Podem ser alterados posteriormente pela equipe conforme a fonte adotada.

START TRANSACTION;





















COMMIT;

-- ============================================================
-- VIEWS PARA O BACKEND / DASHBOARD
-- ============================================================

CREATE OR REPLACE VIEW vw_dashboard AS
SELECT
    m.id_medicao, m.id_registro_csv, m.data_hora,
    DATE(m.data_hora) AS data_medicao, TIME(m.data_hora) AS horario,
    z.nome_zona AS zona_cluster, t.nome_turno AS turno, st.nome_status AS status_eficiencia,
    m.consumo_total_kwh, m.energia_gpus_kwh, m.energia_refrigeracao_kwh,
    CASE WHEN m.consumo_total_kwh >= (m.energia_gpus_kwh + m.energia_refrigeracao_kwh) THEN ROUND(m.consumo_total_kwh - m.energia_gpus_kwh - m.energia_refrigeracao_kwh, 2) ELSE NULL END AS energia_nao_categorizada_kwh,
    CASE WHEN (m.energia_gpus_kwh + m.energia_refrigeracao_kwh) > m.consumo_total_kwh THEN 1 ELSE 0 END AS inconsistencia_energia,
    CASE WHEN m.consumo_total_kwh > 0 THEN ROUND((m.energia_gpus_kwh / m.consumo_total_kwh) * 100, 2) ELSE 0 END AS participacao_gpus_pct,
    CASE WHEN m.consumo_total_kwh > 0 THEN ROUND((m.energia_refrigeracao_kwh / m.consumo_total_kwh) * 100, 2) ELSE 0 END AS participacao_refrigeracao_pct,
    m.consumo_agua_l, m.agua_reaproveitada_l,
    CASE WHEN m.consumo_agua_l >= m.agua_reaproveitada_l THEN ROUND(m.consumo_agua_l - m.agua_reaproveitada_l, 2) ELSE NULL END AS agua_nao_reaproveitada_l,
    CASE WHEN m.agua_reaproveitada_l > m.consumo_agua_l THEN 1 ELSE 0 END AS inconsistencia_agua,
    CASE WHEN m.consumo_agua_l > 0 THEN ROUND((m.agua_reaproveitada_l / m.consumo_agua_l) * 100, 2) ELSE 0 END AS agua_reaproveitada_pct,
    m.utilizacao_gpus_pct, m.eficiencia_energetica_pct, m.eficiencia_hidrica_pct
FROM medicao_datacenter m
INNER JOIN zona_cluster z ON z.id_zona = m.id_zona
INNER JOIN turno t ON t.id_turno = m.id_turno
INNER JOIN status_eficiencia st ON st.id_status = m.id_status;

CREATE OR REPLACE VIEW vw_custos_sustentabilidade AS
SELECT
    m.id_medicao, m.data_hora, z.nome_zona AS zona_cluster,
    m.consumo_total_kwh, m.consumo_agua_l,
    p.tarifa_energia_kwh, p.tarifa_agua_m3, p.fator_emissao_co2,
    ROUND(m.consumo_total_kwh * p.tarifa_energia_kwh, 2) AS custo_energia_rs,
    ROUND((m.consumo_agua_l / 1000) * p.tarifa_agua_m3, 2) AS custo_agua_rs,
    ROUND((m.consumo_total_kwh * p.tarifa_energia_kwh) + ((m.consumo_agua_l / 1000) * p.tarifa_agua_m3), 2) AS custo_operacional_rs,
    ROUND(m.consumo_total_kwh * p.fator_emissao_co2, 3) AS emissao_co2_kgco2e
FROM medicao_datacenter m
INNER JOIN zona_cluster z ON z.id_zona = m.id_zona
LEFT JOIN parametros_sustentabilidade p ON DATE(m.data_hora) >= p.data_inicio AND (p.data_fim IS NULL OR DATE(m.data_hora) <= p.data_fim);

CREATE OR REPLACE VIEW vw_dashboard_completa AS
SELECT d.*, c.custo_energia_rs, c.custo_agua_rs, c.custo_operacional_rs, c.emissao_co2_kgco2e
FROM vw_dashboard d LEFT JOIN vw_custos_sustentabilidade c ON c.id_medicao = d.id_medicao;

CREATE OR REPLACE VIEW vw_resumo_diario AS
SELECT DATE(m.data_hora) AS data, z.nome_zona AS zona_cluster, COUNT(*) AS total_medicoes, ROUND(SUM(m.consumo_total_kwh), 2) AS consumo_total_kwh, ROUND(SUM(m.energia_gpus_kwh), 2) AS energia_gpus_kwh, ROUND(SUM(m.energia_refrigeracao_kwh), 2) AS energia_refrigeracao_kwh, ROUND(SUM(m.consumo_agua_l), 2) AS consumo_agua_l, ROUND(SUM(m.agua_reaproveitada_l), 2) AS agua_reaproveitada_l, ROUND(AVG(m.utilizacao_gpus_pct), 2) AS utilizacao_media_gpus_pct, ROUND(AVG(m.eficiencia_energetica_pct), 2) AS eficiencia_energetica_media_pct, ROUND(AVG(m.eficiencia_hidrica_pct), 2) AS eficiencia_hidrica_media_pct FROM medicao_datacenter m INNER JOIN zona_cluster z ON z.id_zona = m.id_zona GROUP BY DATE(m.data_hora), z.id_zona, z.nome_zona;

CREATE OR REPLACE VIEW vw_resumo_zona AS
SELECT z.id_zona, z.nome_zona, COUNT(*) AS total_medicoes, ROUND(AVG(m.consumo_total_kwh), 2) AS consumo_medio_kwh, ROUND(AVG(m.energia_gpus_kwh), 2) AS energia_gpu_media_kwh, ROUND(AVG(m.energia_refrigeracao_kwh), 2) AS refrigeracao_media_kwh, ROUND(AVG(m.consumo_agua_l), 2) AS consumo_agua_medio_l, ROUND(AVG(m.agua_reaproveitada_l), 2) AS agua_reaproveitada_media_l, ROUND(AVG(m.utilizacao_gpus_pct), 2) AS utilizacao_gpu_media_pct, ROUND(AVG(m.eficiencia_energetica_pct), 2) AS eficiencia_energetica_media_pct, ROUND(AVG(m.eficiencia_hidrica_pct), 2) AS eficiencia_hidrica_media_pct FROM medicao_datacenter m INNER JOIN zona_cluster z ON z.id_zona = m.id_zona GROUP BY z.id_zona, z.nome_zona;

CREATE OR REPLACE VIEW vw_resumo_turno AS
SELECT t.id_turno, t.nome_turno, COUNT(*) AS total_medicoes, ROUND(AVG(m.consumo_total_kwh), 2) AS consumo_medio_kwh, ROUND(AVG(m.consumo_agua_l), 2) AS consumo_agua_medio_l, ROUND(AVG(m.utilizacao_gpus_pct), 2) AS utilizacao_gpu_media_pct, ROUND(AVG(m.eficiencia_energetica_pct), 2) AS eficiencia_energetica_media_pct, ROUND(AVG(m.eficiencia_hidrica_pct), 2) AS eficiencia_hidrica_media_pct FROM medicao_datacenter m INNER JOIN turno t ON t.id_turno = m.id_turno GROUP BY t.id_turno, t.nome_turno;

CREATE OR REPLACE VIEW vw_resumo_status AS
SELECT s.id_status, s.nome_status, COUNT(*) AS quantidade, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM medicao_datacenter), 2) AS percentual FROM medicao_datacenter m INNER JOIN status_eficiencia s ON s.id_status = m.id_status GROUP BY s.id_status, s.nome_status;

SET FOREIGN_KEY_CHECKS = 1;

-- Validações rápidas:
SELECT COUNT(*) AS total_medicoes FROM medicao_datacenter;
SELECT COUNT(*) AS total_zonas FROM zona_cluster;
SELECT COUNT(*) AS total_turnos FROM turno;
SELECT COUNT(*) AS total_status FROM status_eficiencia;
SELECT MIN(data_hora) AS primeira_medicao, MAX(data_hora) AS ultima_medicao FROM medicao_datacenter;